public class InnerDataAutomationProjectImageOverrideConfigurationFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration>
{

    internal InnerDataAutomationProjectSensitiveDataConfigurationFactory SensitiveDataConfigurationFactory { get; set; }

    internal InnerDataAutomationProjectModalityProcessingConfigurationFactory ModalityProcessingFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration Create()
    {
        var imageOverrideConfigurationResult = CreateImageOverrideConfiguration();
        factoryAction?.Invoke(imageOverrideConfigurationResult);

        return imageOverrideConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration CreateImageOverrideConfiguration()
    {
        var imageOverrideConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration();

        return imageOverrideConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.ImageOverrideConfiguration result)
    {
        base.CreateChildren(result);

        result.SensitiveDataConfiguration ??= SensitiveDataConfigurationFactory?.Build();
        result.ModalityProcessing ??= ModalityProcessingFactory?.Build();
    }

} // End Of Class

